-- Dumping data for table smartcity360.city_policies: ~12 rows (approximately)
INSERT INTO `city_policies` (`id`, `name`, `description`, `dsl_text`, `enabled`, `version`, `created_by`, `created_at`, `updated_at`) VALUES
	(1, 'Residential Night Noise Limit', 'Max noise allowed in residential zones at night', 'IF noise > 55 AND zone = "RESIDENTIAL" THEN FINE 5000', 1, 1, 1, '2023-08-01 09:00:00', '2026-11-10 10:37:32'),
	(2, 'Residential Day Noise Limit', 'Max noise allowed in residential zones during the day', 'IF noise > 70 AND zone = "RESIDENTIAL" THEN FINE 3000', 1, 1, 1, '2023-08-01 09:05:00', '2026-11-10 10:37:32'),
	(3, 'Commercial Noise Limit', 'Max noise allowed in commercial zones', 'IF noise > 75 AND zone = "COMMERCIAL" THEN FINE 10000', 1, 1, 1, '2023-08-02 10:00:00', '2026-11-06 22:19:08'),
	(4, 'Industrial Noise Limit', 'Max noise allowed in industrial zones', 'IF noise > 90 AND zone = "INDUSTRIAL" THEN FINE 20000', 1, 1, 1, '2023-08-02 10:15:00', '2026-11-06 22:19:08'),
	(5, 'Hazardous Air Quality Alert', 'Trigger a city-wide alert if AQI goes into hazardous levels', 'IF air_quality > 150 THEN ALERT "HAZARDOUS_AIR"', 1, 1, 1, '2023-08-03 11:30:00', '2026-11-10 10:41:36'),
	(6, 'Poor Air Quality Warning', 'Warning for sensitive groups', 'IF air_quality > 100 AND air_quality <= 150 THEN ALERT "POOR_AIR"', 1, 1, 1, '2023-08-03 11:35:00', '2026-11-10 10:41:36'),
	(7, 'Industrial Emission Limit', 'Strict AQI limit for industrial zones', 'IF air_quality > 120 AND zone = "INDUSTRIAL" THEN FINE 50000', 1, 1, 1, '2023-08-04 14:00:00', '2026-11-06 22:19:08'),
	(8, 'Extreme Heat Warning', 'Alert citizens when temperature exceeds 38 degrees', 'IF temperature > 38 THEN ALERT "EXTREME_HEAT"', 1, 1, 1, '2023-08-05 08:00:00', '2026-11-10 10:41:36'),
	(9, 'Public Park Heat Measure', 'Trigger misting systems in parks during extreme heat', 'IF temperature > 35 AND zone = "RESIDENTIAL" THEN ALERT "MISTING_ON"', 1, 1, 9, '2023-08-05 08:20:00', '2026-11-10 10:41:36'),
	(10, 'Construction Noise & Time', 'Heavy fines for construction noise during off-hours', 'IF noise > 65 AND zone = "RESIDENTIAL" THEN FINE 15000', 1, 1, 9, '2023-08-06 09:00:00', '2026-11-10 10:39:52'),
	(11, 'Power Grid Emergency Shutdown', 'Shut down non-critical zones to prevent grid overload', 'IF temperature > 35 AND zone = "INDUSTRIAL" THEN ALERT "SHUTDOWN_POWER"', 1, 1, 9, '2023-08-07 15:45:00', '2026-11-10 10:41:36'),
	(12, 'Old Noise Limit (Deprecated)', 'Old rule that was replaced by ID 1', 'IF noise > 60 AND zone = "RESIDENTIAL" THEN FINE 2000', 0, 1, 9, '2023-07-15 10:00:00', '2026-11-06 22:19:08'),
	(13, 'Residential Parking Hours', 'Restricts parking in residential zones between 22:00 (10 PM) and 06:00 (6 AM)', 'IF hour >= 22.00 AND hour < 6 AND zone = "RESIDENTIAL" THEN FINE 5000', 1, 1, 1, '2026-11-09 18:55:19', '2026-11-10 10:41:36');

